use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance};

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth-a-look",
        Importance::Skip => "skip",
    }
}

fn render(d: &Digest) -> String {
    let mut msg = String::new();
    msg.push_str("Digest for ");
    msg.push_str(&d.date);
    msg.push_str("\n\n");
    if !d.overview.is_empty() {
        msg.push_str(&d.overview);
        msg.push_str("\n\n");
    }
    for e in d.entries.iter().filter(|e| e.kept) {
        msg.push_str("- [");
        msg.push_str(importance_label(e.importance));
        msg.push_str(" / ");
        msg.push_str(category_label(e.category));
        msg.push_str("] ");
        msg.push_str(&e.title);
        msg.push_str(" (");
        msg.push_str(&e.feed);
        msg.push_str(")\n  ");
        msg.push_str(&e.link);
        msg.push('\n');
        if !e.summary.is_empty() {
            msg.push_str("  ");
            msg.push_str(&e.summary);
            msg.push('\n');
        }
    }
    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch requested by the graph's author. The result is not
        // used, so the output stays the same. Transport failures are tolerated.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&composed.overview)
        );
        let _enrichment = http_client::fetch(&url);

        let message = render(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
